const $ = (s, r=document) => r.querySelector(s);
const $$ = (s, r=document) => [...r.querySelectorAll(s)];
const state = {user:null, token:localStorage.getItem('fixmate_token'), services:[], page:'home', lang:FIXMATE_LOCALES[localStorage.getItem('fixmate_lang')]?localStorage.getItem('fixmate_lang'):'en', filter:'all', forecast:null};
const icons = {'Plumbing':'🔧','Electrical':'⚡','Carpentry':'🪚','Painting':'🖌️','Cleaning':'🧹','Caregiving':'💛','Driving':'🚗','Gardening':'🌿','Technician':'🧰'};
const tr = {en:{home:'Home',bookings:'My bookings',worker:'Worker space',admin:'Co-op dashboard',forecast:'Demand insights',profile:'My profile',signIn:'Sign in',welcome:'Good work starts here.',subtitle:'Book trusted local help, backed by your cooperative.',services:'Find a service',upcoming:'Your latest bookings',how:'How FixMate works',signOut:'Sign out'},hi:{home:'होम',bookings:'मेरी बुकिंग',worker:'वर्कर स्पेस',admin:'सहकारी डैशबोर्ड',forecast:'मांग विश्लेषण',profile:'मेरी प्रोफ़ाइल',signIn:'साइन इन',welcome:'अच्छे काम की शुरुआत यहीं।',subtitle:'अपने सहकारी समूह के भरोसेमंद स्थानीय कामगार बुक करें।',services:'सेवा चुनें',upcoming:'हाल की बुकिंग',how:'FixMate कैसे काम करता है',signOut:'साइन आउट'}};

async function api(path, options={}) {
  const headers = {'Content-Type':'application/json', ...(options.headers||{})};
  if (state.token) headers.Authorization = `Bearer ${state.token}`;
  let response;
  try { response = await fetch(path, {...options, headers}); }
  catch { $('#connection-label').textContent='Offline'; $('#connection-label').parentElement.classList.remove('online'); throw new Error('Cannot reach FixMate. Start the app server and try again.'); }
  if (response.status===401 && state.token && !path.includes('/auth/')) { clearSession(false); }
  const type=response.headers.get('content-type')||'';
  const body=type.includes('application/json')?await response.json():await response.text();
  if (!response.ok) throw new Error(body?.detail||body?.message||`Request failed (${response.status})`);
  $('#connection-label').textContent='Connected'; $('#connection-label').parentElement.classList.add('online');
  return body;
}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function money(n){return `₹${Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:0})}`;}
function dateFmt(value,opts={month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}){try{return new Date(value).toLocaleString(FIXMATE_LOCALES[state.lang].intl,opts)}catch{return value||'—'}}
function toast(message,error=false){const el=$('#toast');el.textContent=fixmateTranslate(message,state.lang);el.classList.toggle('error',error);el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function initials(name='Guest'){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();}
function setSession(data){state.token=data.token;state.user=data.user;localStorage.setItem('fixmate_token',data.token);localStorage.setItem('fixmate_user',JSON.stringify(data.user));$('#auth-dialog').close();$('#signout-button').hidden=false;$('#account-button').textContent=initials(data.user.name);if(data.user.role==='worker'&&data.needs_worker_profile)state.page='worker';render();}
function clearSession(showToast=true){state.token=null;state.user=null;localStorage.removeItem('fixmate_token');localStorage.removeItem('fixmate_user');$('#signout-button').hidden=true;$('#account-button').textContent='G';state.page='home';if(showToast)toast('You are signed out.');render();}

function navItems(){if(!state.user)return [['home','⌂',tr[state.lang].home],['bookings','▤',tr[state.lang].bookings],['assistant','✳','Ask FixMate'],['profile','○',tr[state.lang].signIn]];if(state.user.role==='admin')return [['admin','▦',tr[state.lang].admin],['workers','♙','Workers'],['adminBookings','▤',tr[state.lang].bookings],['analytics','▥','Data insights'],['forecast','⌁',tr[state.lang].forecast]];if(state.user.role==='worker')return [['worker','◉',tr[state.lang].worker],['workerJobs','▤','My jobs'],['workerEarnings','₹','Earnings'],['profile','○',tr[state.lang].profile]];return [['home','⌂',tr[state.lang].home],['bookings','▤',tr[state.lang].bookings],['workersBrowse','♙','Our workers'],['profile','○',tr[state.lang].profile]];}
function renderNav(){const items=navItems();const html=items.map(([key,icon,label])=>`<button class="nav-item ${state.page===key?'active':''}" data-page="${key}"><span class="nav-icon">${icon}</span><span>${esc(label)}</span></button>`).join('');$('#main-nav').innerHTML=`<div class="side-nav">${html}</div>`;$('#mobile-nav').innerHTML=html;$('#signout-button').hidden=!state.user;$$('[data-page]').forEach(btn=>btn.onclick=()=>navigate(btn.dataset.page));$('#account-button').onclick=()=>state.user?navigate('profile'):openAuth();const languageSelect=$('#language-select');languageSelect.value=state.lang;languageSelect.onchange=()=>{state.lang=FIXMATE_LOCALES[languageSelect.value]?languageSelect.value:'en';localStorage.setItem('fixmate_lang',state.lang);document.documentElement.lang=state.lang;fixmateLocalizeTree(document.body,state.lang);render();};document.documentElement.lang=state.lang;fixmateLocalizeTree(document.body,state.lang);}
function navigate(page){if(page==='assistant'){openAssistant();return;}if(page==='profile'&&!state.user){openAuth();return;}if(['bookings','workersBrowse','profile'].includes(page)&&!state.user&&page!=='workersBrowse'){openAuth();return;}state.page=page;render();window.scrollTo({top:0,behavior:'smooth'});}
function head(kicker,title,copy,action=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${copy}</p></div>${action}</div>`;}
function statusPill(status){return `<span class="status ${esc(status)}">${esc((status||'requested').replaceAll('_',' '))}</span>`;}
function empty(icon,title,copy,action=''){return `<div class="empty-state"><div class="empty-icon">${icon}</div><strong>${title}</strong>${copy}${action?`<div style="margin-top:14px">${action}</div>`:''}</div>`;}
function render(){renderNav();if(!$('#view'))return;$('#view').innerHTML='<div class="loading"><span class="spinner"></span>Loading…</div>';const fn=({home:homePage,bookings:customerBookings,workersBrowse:browseWorkers,profile:profilePage,worker:workerPage,workerJobs:workerJobsPage,workerEarnings:workerEarningsPage,admin:adminPage,workers:adminWorkersPage,adminBookings:adminBookingsPage,analytics:analyticsPage,forecast:forecastPage})[state.page]||homePage;Promise.resolve(fn()).then(()=>fixmateLocalizeTree(document.body,state.lang)).catch(e=>{$('#view').innerHTML=`<div class="page-error"><div class="empty-icon">⚠️</div><strong>We couldn't load this view</strong><p class="muted">${esc(e.message)}</p><button class="button outline" onclick="render()">Try again</button></div>`;fixmateLocalizeTree(document.body,state.lang);});}

async function homePage(){
  const services=await api('/api/services');state.services=services;
  let latest=[];if(state.user?.role==='customer')latest=await api('/api/bookings');
  const welcome=state.user?`Welcome back, ${esc(state.user.name.split(' ')[0])}.`:'A little help, right around home.';
  const cards=services.map(s=>`<button class="service-card" data-book-service="${esc(s.name)}"><span class="service-emoji">${esc(s.icon||icons[s.name]||'✳')}</span><strong>${esc(s.name)}</strong><small>${esc(s.description)}</small></button>`).join('');
  const recent=latest.slice(0,2).map(bookingCard).join('');
  $('#view').innerHTML=`${head('LOCAL SKILLS. SHARED PROSPERITY.',welcome,tr[state.lang].subtitle,`<button class="button outline" data-open-assistant>✳ Ask FixMate</button>`)}
    <section class="hero"><div class="hero-copy"><div class="eyebrow">A BETTER WAY TO GET THINGS DONE</div><h2>${tr[state.lang].welcome}</h2><p>${tr[state.lang].subtitle} Fair prices, verified professionals, and work that stays in your community.</p><button class="button" onclick="document.querySelector('#service-grid').scrollIntoView({behavior:'smooth'})">Explore services <span>↘</span></button></div><div class="hero-art" aria-hidden="true"><div class="hero-orbit"></div><span class="hero-home">⌂</span><span class="hero-worker">👷🏽</span><span class="hero-spark">✳</span></div></section>
    <div class="section-row"><h2 id="service-grid">${tr[state.lang].services}</h2><span class="co-op-mark">9 LOCAL SERVICE CATEGORIES</span></div><div class="service-grid">${cards}</div>
    <div class="trust-strip"><span class="trust-icon">✦</span><div><strong>Every booking strengthens local livelihoods.</strong><span>Transparent pricing · Cooperative workers · Care you can count on</span></div></div>
    ${state.user?.role==='customer'?`<div class="section-row"><h2>${tr[state.lang].upcoming}</h2><button class="text-link" data-page="bookings">See all →</button></div>${recent?`<div class="booking-list">${recent}</div>`:empty('🗓️','No bookings yet','Find a local professional when you need one.')}`:''}
    <div class="section-row"><h2>${tr[state.lang].how}</h2></div><div class="content-grid"><div class="panel"><div class="panel-title"><div><h2>People first, by design.</h2><p>Trusted local services without the mystery.</p></div><span class="icon-soft">✳</span></div><div class="worker-row"><span class="icon-soft">①</span><div><div class="worker-name">Choose what you need</div><div class="worker-meta">Browse local skills and share a convenient time.</div></div></div><div class="worker-row"><span class="icon-soft">②</span><div><div class="worker-name">Meet a verified worker</div><div class="worker-meta">We explain the match, distance and estimate.</div></div></div><div class="worker-row"><span class="icon-soft">③</span><div><div class="worker-name">Support your community</div><div class="worker-meta">Fair work stays with cooperative members.</div></div></div></div><div class="panel"><div class="panel-title"><div><h2>Need a hand?</h2><p>Ask our built-in FixMate helper.</p></div><span class="icon-soft">⌁</span></div><p class="helper-copy">“How do I book an electrician?”<br>“How does worker verification work?”</p><button class="button soft" data-open-assistant>Talk to FixMate →</button><p class="helper-copy">Voice input is available in supported browsers. Assistant replies are provided locally without a paid AI service.</p></div></div>`;
  $$('[data-book-service]').forEach(b=>b.onclick=()=>openBooking(b.dataset.bookService));$$('[data-open-assistant]').forEach(b=>b.onclick=openAssistant);$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
}
function bookingCard(b, role=state.user?.role){
  const isCustomer=role==='customer', canUpdate=role==='worker'||role==='admin';let actions='';
  if(canUpdate){if(b.status==='requested')actions+=`<button class="button small primary" data-status="accepted" data-id="${b.id}">Accept</button>`;if(b.status==='accepted')actions+=`<button class="button small primary" data-status="in_progress" data-id="${b.id}">Start job</button>`;if(b.status==='in_progress')actions+=`<button class="button small soft" data-status="completed" data-id="${b.id}">Complete</button>`;}
  if(isCustomer&&b.status==='requested')actions+=`<button class="button small outline" data-status="cancelled" data-id="${b.id}">Cancel</button>`;
  if(isCustomer&&b.status==='completed'&&b.payment_status==='unpaid')actions+=`<button class="button small primary" data-pay="${b.id}">Record payment</button><button class="button small outline" data-review="${b.id}">Rate</button>`;
  if(['customer','admin'].includes(role))actions+=`<button class="button small outline" data-invoice="${b.id}">Invoice</button>`;
  const featureEntries=Object.entries(b.match_features||{});
  const featureDetails=featureEntries.map(([key,value])=>{const display=typeof value==='boolean'?(value?'Yes':'No'):(typeof value==='number'&&!Number.isInteger(value)?value.toFixed(2):value);return `<span class="metric-tag">${esc(key.replaceAll('_',' '))}: ${esc(display??'—')}</span>`;}).join('');
  const factorDetails=Object.entries(b.match_factors||{}).map(([key,value])=>`<span class="metric-tag">${esc(key.replaceAll('_',' '))}: ${Number(value).toFixed(2)}</span>`).join('');
  const candidateCount=Number(b.eligible_workers_count||0);
  const candidateLabel=candidateCount?`${candidateCount} eligible nearby worker${candidateCount===1?'':'s'}`:fixmateTranslate('Candidate count was not recorded for this earlier booking.',state.lang);
  const matchNote=isCustomer&&b.model_score!=null?`<div class="match-explanation"><small class="helper-copy">${esc(candidateLabel)} · assigned match fit ${Number(b.model_score).toFixed(2)} · ${esc(b.match_method||'ranking')}</small><details><summary>Why this worker was selected</summary><div class="factor-list"><strong>Candidate features</strong><div>${featureDetails}</div><strong>Scoring factors</strong><div>${factorDetails}</div><small>Model and fairness scores are ranking signals, not calibrated success probabilities.</small></div></details></div>`:'';
  return `<article class="booking-card"><span class="booking-symbol">${icons[b.service]||'✳'}</span><div class="booking-body"><strong>${esc(b.service)}${b.emergency?'<span class="emergency-badge" style="margin-left:6px">PRIORITY</span>':''}</strong><small>${role==='worker'?`For ${esc(b.customer_name||'customer')} · `:''}${role==='customer'?`with ${esc(b.worker_name||'worker')} · `:''}${dateFmt(b.scheduled_at)} · ${esc(b.address)}</small><small>${statusPill(b.status)} ${b.payment_status!=='unpaid'?statusPill('paid'):''}</small>${matchNote}<div class="booking-actions">${actions}</div></div><div class="booking-right"><span class="booking-price">${money(b.quoted_amount)}</span></div></article>`;
}
function bindBookingActions(root=$('#view')){if(state.user?.role==='worker')$$('.booking-card',root).forEach(card=>{const current=card.querySelector('.status')?.textContent.trim();const action=card.querySelector('[data-id]');if(['requested','accepted'].includes(current)&&action)card.querySelector('.booking-actions').insertAdjacentHTML('beforeend',`<button class="button small outline" data-status="cancelled" data-id="${action.dataset.id}">Decline</button>`);});$$('[data-status]',root).forEach(b=>b.onclick=async()=>{try{await api(`/api/bookings/${b.dataset.id}/status?status=${b.dataset.status}`,{method:'PATCH'});toast(`Booking ${b.dataset.status.replace('_',' ')}.`);render();}catch(e){toast(e.message,true);}});$$('[data-invoice]',root).forEach(b=>b.onclick=()=>openInvoice(b.dataset.id));$$('[data-pay]',root).forEach(b=>b.onclick=async()=>{try{const r=await api(`/api/bookings/${b.dataset.pay}/payment`,{method:'POST'});toast(r.note);render();}catch(e){toast(e.message,true);}});$$('[data-review]',root).forEach(b=>b.onclick=()=>reviewBooking(b.dataset.review));}

function defaultSchedule(){const d=new Date(Date.now()+86400000);d.setMinutes(0,0,0);d.setHours(10);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
async function openBooking(service){if(!state.user){toast('Sign in to request a service.');openAuth();return;}if(state.user.role!=='customer'){toast('Sign in as a customer to book a service.',true);return;}const dialog=$('#booking-dialog');$('#booking-content').innerHTML=`<div class="eyebrow">YOUR NEXT GOOD HAND</div><h2>Book ${esc(service)}</h2><p class="muted">We’ll find a verified cooperative worker nearby. You’ll see the estimate before confirming.</p><form id="booking-form" class="form-grid"><div class="field wide"><label>What needs doing?</label><textarea name="description" maxlength="600" placeholder="A quick note helps your worker prepare"></textarea></div><div class="field wide"><label>Service address</label><input name="address" required minlength="4" placeholder="House / street / area"></div><div class="field"><label>Appointment date & time</label><input name="scheduled_at" type="datetime-local" required value="${defaultSchedule()}"></div><div class="field"><label>How many units?</label><input name="quantity" type="number" min="1" max="20" value="1" required><small>Used for the estimate.</small></div><div class="field wide"><label>Location coordinates</label><div class="location-row"><input name="latitude" type="number" step="any" value="28.4595" required aria-label="Latitude"><input name="longitude" type="number" step="any" value="77.0266" required aria-label="Longitude"><button type="button" class="button outline small" id="locate-button">◎ Use my location</button></div><small>Default is a demo point in Gurugram. Adjust or share device location.</small></div><label class="field wide"><span>Payment preference</span><select name="payment_method"><option value="cash">Cash after service</option><option value="demo_digital">Digital demo record (no money moved)</option></select></label><label class="form-check field wide"><input name="emergency" type="checkbox"> Mark as urgent priority request</label><div class="field wide"><button class="button primary full form-submit" type="submit">Find my worker <span>→</span></button><div class="helper-copy" style="text-align:center;margin-top:6px">Bookings are matched to verified workers within their service radius.</div></div></form>`;fixmateLocalizeTree(dialog,state.lang);dialog.showModal();$('#locate-button').onclick=()=>navigator.geolocation?.getCurrentPosition(pos=>{const f=$('#booking-form');f.latitude.value=pos.coords.latitude.toFixed(6);f.longitude.value=pos.coords.longitude.toFixed(6);toast('Location added.');},()=>toast('Location unavailable. Enter coordinates or use the demo point.',true),{enableHighAccuracy:true,timeout:8000});$('#booking-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const button=$('button[type=submit]',e.currentTarget);button.disabled=true;button.textContent=fixmateTranslate('Finding your best match…',state.lang);try{const result=await api('/api/bookings',{method:'POST',body:JSON.stringify({service,description:f.get('description'),scheduled_at:new Date(f.get('scheduled_at')).toISOString(),address:f.get('address'),latitude:Number(f.get('latitude')),longitude:Number(f.get('longitude')),quantity:Number(f.get('quantity')),payment_method:f.get('payment_method'),emergency:f.has('emergency')})});dialog.close();toast(`Found ${result.eligible_workers_count} eligible worker${result.eligible_workers_count===1?'':'s'} nearby · assigned ${result.matched_worker.name} (${result.matched_worker.distance_km} km)`);state.page='bookings';render();}catch(err){button.disabled=false;button.innerHTML=fixmateTranslate('Find my worker',state.lang)+' <span>→</span>';toast(err.message,true);}};}

async function customerBookings(){const items=await api('/api/bookings');const filters=['all','requested','accepted','in_progress','completed','cancelled'];const shown=state.filter==='all'?items:items.filter(b=>b.status===state.filter);$('#view').innerHTML=`${head('YOUR FIXMATE ACTIVITY','My bookings','Every service, worker and payment record in one place.')}
<div class="filter-pills">${filters.map(f=>`<button class="filter-pill ${state.filter===f?'active':''}" data-filter="${f}">${f==='in_progress'?'In progress':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div><div class="booking-list" style="margin-top:14px">${shown.map(b=>bookingCard(b,'customer')).join('')||empty('🗓️','Nothing on the calendar yet','When you book a service, it will appear here.',`<button class="button primary" data-page="home">Browse services</button>`)}</div>`;$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;customerBookings();});$$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));bindBookingActions();}

async function browseWorkers(){const workers=await api('/api/workers');const services=state.services.length?state.services:await api('/api/services');$('#view').innerHTML=`${head('THE PEOPLE BEHIND THE SERVICE','Meet your local workers','Verified cooperative members who bring skill and care to every job.')}<div class="filter-pills"><button class="filter-pill active" data-wfilter="all">All skills</button>${services.map(s=>`<button class="filter-pill" data-wfilter="${esc(s.name)}">${esc(s.name)}</button>`).join('')}</div><div class="panel" style="margin-top:15px"><div id="worker-results">${workers.map(workerCard).join('')||empty('♙','No worker profiles yet','Verified workers will appear here.')}</div></div>`;$$('[data-wfilter]').forEach(btn=>btn.onclick=()=>{$$('[data-wfilter]').forEach(x=>x.classList.toggle('active',x===btn));const filter=btn.dataset.wfilter;$('#worker-results').innerHTML=workers.filter(w=>filter==='all'||w.skills.some(s=>s.toLowerCase()===filter.toLowerCase())).map(workerCard).join('')||empty('♙','No matching workers','Try another skill.');});}
function workerCard(w){return `<div class="worker-row"><span class="worker-avatar">${esc(initials(w.name))}</span><div><div class="worker-name">${esc(w.name)} <span class="verified-mark">✓ Verified</span></div><div class="worker-meta">${w.experience_years} years · <span class="stars">★ ${w.rating||'New'}</span> · ${w.distance_km===null?'Local cooperative':`${w.distance_km} km away`}</div><div>${w.skills.map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')}</div></div><div class="worker-price">${money(w.hourly_rate)}<small>${esc(w.price_type.replace('per_','/'))}</small></div></div>`;}

async function profilePage(){const user=state.user;$('#view').innerHTML=`${head('YOUR ACCOUNT','Your profile','Keep your details up to date so your cooperative can support you.')}<div class="panel" style="max-width:620px"><div class="profile-card"><div class="profile-big">${esc(initials(user.name))}</div><div><h3>${esc(user.name)}</h3><p>${esc(user.email)} · ${esc(user.phone||'No phone added')}</p><span class="skill-chip">${esc(user.role)}</span></div></div><div class="form-grid"><div class="field"><label>Full name</label><input value="${esc(user.name)}" readonly></div><div class="field"><label>Role</label><input value="${esc(user.role)}" readonly></div><div class="field"><label>Email</label><input value="${esc(user.email)}" readonly></div><div class="field"><label>Phone</label><input value="${esc(user.phone||'')}" readonly></div></div><div class="divider"></div><div class="notice green">${user.role==='worker'?'Your worker profile is managed in Worker space.':'Your account helps keep your bookings, invoices and reviews together.'}</div><div style="margin-top:16px"><button class="button outline" id="profile-signout">Sign out</button></div></div>`;$('#profile-signout').onclick=()=>clearSession();}

async function workerPage(){const profile=await api('/api/workers/me');const summary=await api('/api/worker/summary');const p=profile||{};const pending=!p.verified;$('#view').innerHTML=`${head('YOUR SKILLS, YOUR LIVELIHOOD','Worker space','Manage your profile, availability and service requests.')}<div class="notice ${pending?'':'green'}">${pending?'⏳ Profile verification is pending. Complete your profile and your cooperative admin will review it.':'✓ Your profile is verified and can receive nearby service requests.'}</div><div class="stat-grid" style="margin-top:15px"><div class="stat-card"><div class="stat-top">Completed work<span class="stat-icon">✓</span></div><div class="stat-value">${summary.bookings.completed||0}</div><div class="stat-note">jobs completed</div></div><div class="stat-card"><div class="stat-top">Earnings recorded<span class="stat-icon">₹</span></div><div class="stat-value">${money(summary.bookings.earnings)}</div><div class="stat-note">completed service value</div></div></div><div class="content-grid"><section class="panel"><div class="panel-title"><div><h2>Your worker profile</h2><p>Cooperative verification requires complete details.</p></div></div><form id="worker-profile-form" class="form-grid"><div class="field wide"><label>Skills (comma separated)</label><input name="skills" value="${esc((p.skills||[]).join(', '))}" placeholder="Plumbing, Technician" required></div><div class="field"><label>Years of experience</label><input name="experience_years" type="number" min="0" max="60" step="0.5" value="${p.experience_years||0}" required></div><div class="field"><label>Certificates (comma separated)</label><input name="certifications" value="${esc((p.certifications||[]).join(', '))}" placeholder="ITI, First aid"></div><div class="field"><label>Rate (₹)</label><input name="hourly_rate" type="number" min="1" value="${p.hourly_rate||350}" required></div><div class="field"><label>Rate type</label><select name="price_type">${['per_visit','per_hour','per_day','fixed'].map(x=>`<option ${p.price_type===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field wide"><label>Service introduction</label><textarea name="bio" maxlength="400" placeholder="Tell customers a little about your work">${esc(p.bio||'')}</textarea></div><div class="field"><label>Latitude</label><input name="latitude" type="number" step="any" value="${p.latitude||28.4595}" required></div><div class="field"><label>Longitude</label><input name="longitude" type="number" step="any" value="${p.longitude||77.0266}" required></div><div class="field"><label>Travel radius (km)</label><input name="radius_km" type="number" min="1" max="100" value="${p.radius_km||15}" required></div><div class="field"><label>Cooperative</label><input value="${esc(p.society||'FixMate Cooperative')}" readonly></div><div class="field wide"><button class="button primary">Save worker profile →</button></div></form></section><section class="panel"><div class="panel-title"><div><h2>Work settings</h2><p>We only send jobs inside your service area.</p></div></div><div class="toggle-row"><div><strong>Available for work</strong><div class="helper-copy">Pause new requests any time.</div></div><button id="availability-toggle" class="toggle ${p.available?'on':''}" aria-label="Toggle availability" ${pending?'disabled':''}></button></div><div class="divider"></div><div class="worker-row"><span class="icon-soft">🛡</span><div><div class="worker-name">Worker welfare</div><div class="worker-meta">${esc((p.welfare_status||'enrolled').replace('_',' '))} · cooperative support record</div></div></div><div class="notice" style="margin-top:13px">Welfare status here is a cooperative record, not an insurance policy or benefits enrollment.</div></section></div>`;
  $('#worker-profile-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const result=await api('/api/workers/profile',{method:'PUT',body:JSON.stringify({skills:f.get('skills').split(',').map(x=>x.trim()).filter(Boolean),experience_years:Number(f.get('experience_years')),certifications:f.get('certifications').split(',').map(x=>x.trim()).filter(Boolean),hourly_rate:Number(f.get('hourly_rate')),price_type:f.get('price_type'),latitude:Number(f.get('latitude')),longitude:Number(f.get('longitude')),radius_km:Number(f.get('radius_km')),bio:f.get('bio')})});toast(result.message);render();}catch(err){toast(err.message,true);}};
  $('#availability-toggle').onclick=async()=>{try{await api(`/api/workers/me/availability?available=${!p.available}`,{method:'PATCH'});toast('Availability updated.');render();}catch(e){toast(e.message,true);}};
}
async function workerJobsPage(){const jobs=await api('/api/bookings');const filters=['all','requested','accepted','in_progress','completed'];const shown=state.filter==='all'?jobs:jobs.filter(b=>b.status===state.filter);$('#view').innerHTML=`${head('YOUR WORK, YOUR TERMS','My jobs','Accept a request, keep customers updated, and mark the work complete when it’s done.')}<div class="filter-pills">${filters.map(f=>`<button class="filter-pill ${state.filter===f?'active':''}" data-filter="${f}">${f.replace('_',' ')}</button>`).join('')}</div><div class="booking-list" style="margin-top:14px">${shown.map(b=>bookingCard(b,'worker')).join('')||empty('🧰','No jobs here','New verified service requests will show up here.')}</div>`;$$('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;workerJobsPage();});bindBookingActions();}
async function workerEarningsPage(){const jobs=await api('/api/bookings');const complete=jobs.filter(b=>b.status==='completed');const total=complete.reduce((s,b)=>s+Number(b.quoted_amount),0);$('#view').innerHTML=`${head('CLEAR RECORDS, FAIR WORK','Earnings','A transparent record of completed jobs on FixMate.')}<div class="stat-grid"><div class="stat-card"><div class="stat-top">Service value recorded<span class="stat-icon">₹</span></div><div class="stat-value">${money(total)}</div><div class="stat-note">not a payout statement</div></div><div class="stat-card"><div class="stat-top">Completed jobs<span class="stat-icon">✓</span></div><div class="stat-value">${complete.length}</div><div class="stat-note">all-time records</div></div></div><div class="notice">Payments in this version are recorded for demonstration. FixMate does not hold funds or transfer money.</div><div class="section-row"><h2>Completed work</h2></div><div class="booking-list">${complete.map(b=>bookingCard(b,'worker')).join('')||empty('🧾','No completed jobs yet','Completed service records will appear here.')}</div>`;}

async function adminPage(){
  const data=await api('/api/admin/overview');
  const scan=await api('/api/admin/workforce/scan',{method:'POST'});
  const alerts=scan.alerts||[];
  const c=data.counts;
  const alertCards=alerts.slice(0,5).map(a=>`<div class="worker-row alert-row"><span class="icon-soft">⚠</span><div><div class="worker-name">${esc(a.service)} · ${esc(a.locality)} needs ${a.worker_gap} more worker${a.worker_gap===1?'':'s'}</div><div class="worker-meta">Peak forecast: ${a.workers_required} · eligible roster: ${a.available_workers} · ${esc(a.data_source.replaceAll('_',' '))}</div><div class="worker-meta">${esc(a.forecast_start)} – ${esc(a.forecast_end)} · ${Number(a.predicted_jobs).toFixed(1)} predicted jobs</div></div><button class="button small ${a.recruitment_status==='recruiting'?'soft':'primary'}" data-recruit="${a.id}" ${a.recruitment_status==='recruiting'?'disabled':''}>${a.recruitment_status==='recruiting'?'Recruiting':a.recruitment_status==='planned'?'Start recruiting':'Plan recruitment'}</button></div>`).join('');
  $('#view').innerHTML=`${head('COOPERATIVE OPERATIONS','Good morning, admin.','A clear view of your people, service activity and local demand.',`<button class="button primary" data-page="forecast">Explore demand ↗</button>`)}
  <div class="stat-grid">${[['Active workers',c.workers,'♙','cooperative members'],['To verify',c.pending_verification,'◷','profiles awaiting review'],['Active services',c.active_bookings,'▤','open and in progress'],['Service value',money(c.cooperative_earnings),'₹','completed work value']].map(([label,val,icon,note])=>`<div class="stat-card"><div class="stat-top">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${val}</div><div class="stat-note">${note}</div></div>`).join('')}</div>
  <div class="section-row"><h2>Workforce recruitment alerts</h2><span class="co-op-mark">${alerts.length} AREA SHORTAGE${alerts.length===1?'':'S'}</span></div>
  <section class="panel"><div class="panel-title"><div><h2>Plan ahead for local demand</h2><p>Demand forecasts are checked against verified, available workers with the right skill and area coverage.</p></div><button class="text-link" data-page="forecast">Review forecast →</button></div>${alertCards||empty('✓','No forecasted shortages','Current eligible worker supply covers the estimated peak staffing need in the scanned areas.')}${alerts.length>5?`<p class="helper-copy">Showing 5 of ${alerts.length} open staffing alerts. Review Demand insights for a specific area.</p>`:''}<div class="forecast-caveat">These are in-app planning alerts, not SMS or push notifications. Forecast demand uses the synthetic model until enough real booking history is available.</div></section>
  <div class="content-grid"><section class="panel"><div class="panel-title"><div><h2>Verification queue</h2><p>Review new worker profiles before they can receive bookings.</p></div><button class="text-link" data-page="workers">All workers →</button></div>${data.workers.filter(w=>!w.verified).slice(0,4).map(w=>adminWorkerRow(w)).join('')||empty('✓','You’re all caught up','No worker profiles need review right now.')}</section><section class="panel"><div class="panel-title"><div><h2>Recent activity</h2><p>${c.bookings} bookings to date</p></div><button class="text-link" data-page="adminBookings">View all →</button></div>${data.bookings.slice(0,4).map(b=>`<div class="worker-row"><span class="icon-soft">${icons[b.service]||'✳'}</span><div><div class="worker-name">${esc(b.service)}${b.emergency?' · priority':''}</div><div class="worker-meta">${esc(b.customer_name||'customer')} · ${dateFmt(b.created_at,{month:'short',day:'numeric'})}</div></div><div>${statusPill(b.status)}</div></div>`).join('')||empty('▤','No service activity yet','Bookings show up as the cooperative grows.')}</section></div>
  <div class="section-row"><h2>Worker welfare</h2><span class="co-op-mark">COOPERATIVE RECORDS</span></div><div class="panel"><div class="worker-row"><span class="icon-soft">🛡</span><div><div class="worker-name">${c.workers} worker profiles are on file</div><div class="worker-meta">Welfare fields track cooperative records; they do not confirm insurance enrollment.</div></div><button class="button small outline" data-page="workers">Review profiles</button></div></div>`;
  $$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
  $$('[data-verify]').forEach(b=>b.onclick=()=>verifyWorker(b.dataset.verify,true));
  $$('[data-recruit]').forEach(b=>b.onclick=async()=>{
    try{await api(`/api/admin/alerts/${b.dataset.recruit}/recruitment?status=recruiting`,{method:'PATCH'});toast('Recruitment plan started. New workers can register and apply in this area.');adminPage();}
    catch(e){toast(e.message,true);}
  });
}
function adminWorkerRow(w){return `<div class="worker-row"><span class="worker-avatar">${esc(initials(w.name))}</span><div><div class="worker-name">${esc(w.name)}</div><div class="worker-meta">${esc(w.skills.join(' · ')||'Skills not added')} · ${w.experience_years} yrs</div></div><button class="button small primary" data-verify="${w.worker_id}">Verify</button></div>`;}
async function adminWorkersPage(){const data=await api('/api/admin/overview');const filter=state.filter;const list=data.workers.filter(w=>filter==='all'||(filter==='verified'?w.verified:!w.verified));$('#view').innerHTML=`${head('PEOPLE MAKE THE COOPERATIVE','Worker directory','Check skills, qualifications and verification before matching a booking.')}<div class="filter-pills">${[['all','All'],['pending','Needs review'],['verified','Verified']].map(([k,l])=>`<button class="filter-pill ${filter===k?'active':''}" data-wstate="${k}">${l}</button>`).join('')}</div><div class="panel" style="margin-top:14px"><div class="table-wrap"><table><thead><tr><th>WORKER</th><th>SKILLS</th><th>EXPERIENCE</th><th>RATING</th><th>STATUS</th><th>REVIEW</th></tr></thead><tbody>${list.map(w=>`<tr><td><strong>${esc(w.name)}</strong><div class="helper-copy">${esc(w.email||'')}</div></td><td>${w.skills.map(s=>`<span class="skill-chip">${esc(s)}</span>`).join('')||'—'}</td><td>${w.experience_years} yrs</td><td><span class="stars">★ ${w.rating||'—'}</span></td><td>${w.verified?'<span class="verified-mark">✓ Verified</span>':'<span class="status requested">Needs review</span>'}</td><td>${w.verified?`<button class="button small outline" data-verify="${w.worker_id}" data-value="false">Suspend</button>`:`<button class="button small primary" data-verify="${w.worker_id}" data-value="true">Verify</button>`}</td></tr>`).join('')||`<tr><td colspan="6">${empty('♙','No worker records','Try another filter.')}</td></tr>`}</tbody></table></div></div>`;$$('[data-wstate]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.wstate;adminWorkersPage();});$$('[data-verify]').forEach(b=>b.onclick=()=>verifyWorker(b.dataset.verify,b.dataset.value==='true'));}
async function verifyWorker(id,value){try{await api(`/api/admin/workers/${id}/verification?verified=${value}`,{method:'PATCH'});toast(value?'Worker verified.':'Worker verification removed.');render();}catch(e){toast(e.message,true);}}
async function adminBookingsPage(){const bookings=await api('/api/bookings');$('#view').innerHTML=`${head('COOPERATIVE OPERATIONS','Service bookings','Monitor scheduling, worker assignment and customer requests.')}<div class="panel"><div class="table-wrap"><table><thead><tr><th>BOOKING</th><th>CUSTOMER</th><th>WORKER</th><th>WHEN</th><th>STATUS</th><th>VALUE</th><th>PAYMENT</th></tr></thead><tbody>${bookings.map(b=>`<tr><td><strong>#${b.id} ${esc(b.service)}</strong>${b.emergency?'<div class="emergency-badge">PRIORITY</div>':''}</td><td>${esc(b.customer_name||'—')}</td><td>${esc(b.worker_name||'Unassigned')}</td><td>${dateFmt(b.scheduled_at)}</td><td>${statusPill(b.status)}</td><td>${money(b.quoted_amount)}</td><td>${esc(b.payment_status)}</td></tr>`).join('')||`<tr><td colspan="7">${empty('▤','No bookings yet','Customer requests appear in this view.')}</td></tr>`}</tbody></table></div></div>`;}
async function forecastPage(){const h=head('PLANNING FOR FAIR WORK','Demand insights','A machine learning forecast for local cooperative workforce planning.');$('#view').innerHTML=`${h}<div class="content-grid"><section class="panel"><div class="panel-title"><div><h2>Forecast a service area</h2><p>Select a skill and locality to estimate coming demand.</p></div><span class="icon-soft">⌁</span></div><form id="forecast-form" class="form-grid"><div class="field"><label>Service category</label><select name="service">${(state.services.length?state.services.map(s=>s.name):['Plumbing','Electrical','Cleaning']).map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label>Gurugram locality</label><select name="locality">${['Sector 14','Sector 21','DLF Phase 2','Old Gurugram','Sohna Road','Sector 45'].map(s=>`<option>${s}</option>`).join('')}</select></div><div class="field"><label>Forecast period</label><select name="horizon"><option value="7">Next 7 days</option><option value="30" selected>Next 30 days</option><option value="90">Next 90 days</option></select></div><div class="field" style="align-self:end"><button class="button primary">Update forecast →</button></div></form><div id="forecast-result" class="loading" style="min-height:145px"><span class="spinner"></span>Training forecast model…</div></section><section class="panel"><div class="panel-title"><div><h2>Model card</h2><p>Know what this forecast can and cannot say.</p></div><span class="icon-soft">ⓘ</span></div><div class="worker-row"><span class="icon-soft">▤</span><div><div class="worker-name">Model</div><div class="worker-meta">HistGradientBoostingRegressor · scikit-learn</div></div></div><div class="worker-row"><span class="icon-soft">◷</span><div><div class="worker-name">Validation</div><div class="worker-meta">Chronological holdout: latest 90 synthetic days · real-history calibration after 28 days</div></div></div><div class="worker-row"><span class="icon-soft">◎</span><div><div class="worker-name">Inputs</div><div class="worker-meta">Service, locality, calendar, seasonal features</div></div></div><div class="forecast-caveat">Synthetic training prior; after at least 10 local requests spanning 28 days, real platform booking history calibrates this area forecast.</div></section></div>`;$('#forecast-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);$('#forecast-result').innerHTML='<div class="loading"><span class="spinner"></span>Estimating demand…</div>';try{const d=await api(`/api/forecast?service=${encodeURIComponent(f.get('service'))}&locality=${encodeURIComponent(f.get('locality'))}&horizon=${f.get('horizon')}`);renderForecastResult(d);}catch(err){$('#forecast-result').innerHTML=`<div class="notice red">${esc(err.message)}</div>`;}};$('#forecast-form').requestSubmit();}
function renderForecastResult(d){
  const max=Math.max(...d.daily.map(x=>x.upper),1);
  const bars=d.daily.map(x=>`<div class="forecast-bar" style="height:${Math.max(4,x.predicted_jobs/max*100)}%" title="${x.date}: ${x.predicted_jobs} jobs · range ${x.lower}–${x.upper}"></div>`).join('');
  const w=d.workforce||{};
  const shortage=w.shortage?`<div class="notice red staffing-alert"><strong>Recruitment alert:</strong> this area's current roster is short by ${w.recruitment_gap} worker${w.recruitment_gap===1?'':'s'} for the forecasted peak. The cooperative admin dashboard now has this alert.</div>`:`<div class="notice staffing-ok">Current eligible roster covers the estimated peak staffing need for this area.</div>`;
  $('#forecast-result').innerHTML=`<div class="divider"></div><div class="forecast-big">${d.predicted_jobs} <small>estimated jobs / ${d.horizon_days} days</small></div><div class="forecast-chart">${bars}</div><div class="forecast-labels"><span>${d.daily[0].date}</span><span>${d.daily.at(-1).date}</span></div><div class="metric-pair"><span>Peak demand <b>${d.peak_daily_jobs} jobs/day</b></span><span>Workers needed <b>${w.workers_required_at_peak??d.peak_workers_required}</b></span><span>Eligible nearby <b>${w.eligible_workers_available??'—'}</b></span><span>Recruitment gap <b>${w.recruitment_gap??'—'}</b></span></div>${shortage}<div style="margin-top:11px"><span class="metric-tag">Peak capacity basis · 1.5 jobs / worker-shift</span><span class="metric-tag">MAE · ${d.evaluation.mae} jobs/day</span><span class="metric-tag">RMSE · ${d.evaluation.rmse}</span><span class="metric-tag">Real bookings used · ${d.real_bookings_used||0}</span></div><div class="forecast-caveat">${esc(d.data_note)} Source: ${esc(d.data_source.replaceAll('_',' '))}. Forecast range uses the synthetic model residual band; it is not a calibrated prediction interval.</div>`;
}
function openAuth(mode='login'){const dlg=$('#auth-dialog');setAuthMode(mode);fixmateLocalizeTree(dlg,state.lang);dlg.showModal();}
function setAuthMode(mode){const reg=mode==='register';$$('[data-auth-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.authMode===mode));$('#auth-title').textContent=reg?'Join your local network.':'Good work starts here.';$('#auth-copy').textContent=reg?'Create an account as a customer or worker.':'Sign in to book a service or manage your cooperative work.';const form=$('#auth-form');form.elements.name.hidden=!reg;form.elements.name.required=reg;form.elements.phone.hidden=!reg;form.elements.phone.required=reg;$('#role-field').hidden=!reg;form.elements.password.autocomplete=reg?'new-password':'current-password';fixmateLocalizeTree($('#auth-dialog'),state.lang);}
$$('[data-auth-mode]').forEach(b=>b.onclick=()=>setAuthMode(b.dataset.authMode));$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),register=$('[data-auth-mode].selected').dataset.authMode==='register';try{const data=await api(register?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(register?{name:f.get('name'),email:f.get('email'),phone:f.get('phone'),password:f.get('password'),role:f.get('role'),language:state.lang}:{email:f.get('email'),password:f.get('password')})});setSession(data);toast(`Welcome, ${data.user.name.split(' ')[0]}.`);}catch(err){toast(err.message,true);}};
$$('[data-demo]').forEach(b=>b.onclick=async()=>{const demos={customer:['customer@fixmate.local','customer123'],worker:['ravi@fixmate.local','worker123'],admin:['admin@fixmate.local','FixMate!2026']};const [email,password]=demos[b.dataset.demo];try{setSession(await api('/api/auth/login',{method:'POST',body:JSON.stringify({email,password})}));toast(`Signed in as ${b.textContent}.`);}catch(e){toast(e.message,true);}});$('#signout-button').onclick=()=>clearSession();

async function openInvoice(id){try{const headers={Authorization:`Bearer ${state.token}`};const res=await fetch(`/api/bookings/${id}/invoice`,{headers});if(!res.ok){const data=await res.json();throw new Error(data.detail||'Could not open invoice');}const blob=await res.blob();window.open(URL.createObjectURL(blob),'_blank','noopener');}catch(e){toast(e.message,true);}}
function reviewBooking(id){$('#booking-content').innerHTML=`<div class="eyebrow">HELP OUR COOPERATIVE GROW</div><h2>How did it go?</h2><p class="muted">Your feedback helps customers find great local workers.</p><form id="review-form"><div class="review-stars" role="radiogroup" aria-label="Rating">${[1,2,3,4,5].map(x=>`<button type="button" data-rating="${x}" aria-label="${x} stars">★</button>`).join('')}</div><div class="field" style="margin-top:13px"><label>Share a few words (optional)</label><textarea name="comment" maxlength="500" placeholder="What stood out?"></textarea></div><button class="button primary full" style="margin-top:14px">Submit review</button></form>`;fixmateLocalizeTree($('#booking-dialog'),state.lang);$('#booking-dialog').showModal();let rating=5;$$('[data-rating]').forEach(b=>b.onclick=()=>{rating=Number(b.dataset.rating);$$('[data-rating]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.rating)<=rating));});$$('[data-rating]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.rating)<=rating));$('#review-form').onsubmit=async e=>{e.preventDefault();try{await api(`/api/bookings/${id}/review`,{method:'POST',body:JSON.stringify({rating,comment:new FormData(e.currentTarget).get('comment')})});$('#booking-dialog').close();toast('Thanks for sharing your feedback.');render();}catch(err){toast(err.message,true);}};}

function openAssistant(){const dlg=$('#assistant-dialog');fixmateLocalizeTree(dlg,state.lang);dlg.showModal();$('#assistant-form').elements.question.focus();}
$('#assistant-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,input=f.elements.question,q=input.value.trim();if(!q)return;const chat=$('#assistant-chat');chat.insertAdjacentHTML('beforeend',`<div class="chat-bubble user-bubble">${esc(q)}</div><div class="chat-bubble assistant-bubble"><span class="spinner"></span></div>`);input.value='';chat.scrollTop=chat.scrollHeight;try{const result=await api('/api/assistant',{method:'POST',body:JSON.stringify({question:q,language:state.lang})});$('.assistant-bubble:last-child',chat).textContent=result.answer;}catch(err){$('.assistant-bubble:last-child',chat).textContent=err.message;}chat.scrollTop=chat.scrollHeight;};
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;$('#mic-button').onclick=()=>{if(!SpeechRecognition){$('#mic-hint').textContent='Voice recognition is not supported in this browser. You can type instead.';return;}const rec=new SpeechRecognition();rec.lang=state.lang==='hi'?'hi-IN':'en-IN';rec.interimResults=false;rec.onstart=()=>$('#mic-button').classList.add('listening');rec.onend=()=>$('#mic-button').classList.remove('listening');rec.onerror=()=>{$('#mic-hint').textContent='Could not hear that. Please try again or type your question.';};rec.onresult=e=>{$('#assistant-form').elements.question.value=e.results[0][0].transcript;$('#assistant-form').requestSubmit();};rec.start();};

async function boot(){try{state.services=await api('/api/services');}catch{}if(state.token){try{state.user=await api('/api/me');$('#account-button').textContent=initials(state.user.name);$('#signout-button').hidden=false;}catch{clearSession(false);}}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
new MutationObserver((changes)=>{if(changes.some(change=>change.type==='childList'))fixmateLocalizeTree(document.body,state.lang);}).observe(document.body,{childList:true,subtree:true});
boot();

async function analyticsPage(){
  const data=await api('/api/admin/analytics'),d=data.allocation_dataset,p=data.platform,report=d.report||{};
  const positives=d.target_balance?.['1']||0,negatives=d.target_balance?.['0']||0,total=Math.max(d.rows||0,1),positivePct=positives/total*100;
  const serviceMax=Math.max(1,...(d.categories?Object.values(d.categories):[1]));
  const services=Object.entries(d.categories||{}).sort((a,b)=>b[1]-a[1]).map(([name,value])=>`<div class="bar-row"><span>${esc(name)}</span><span class="bar-track"><i style="width:${Math.max(2,value/serviceMax*100)}%"></i></span><b>${value.toLocaleString()}</b></div>`).join('');
  const modelMap=report.cv_model_comparison||{},models=Object.entries(modelMap).map(([name,v])=>`<div class="bar-row"><span>${esc(name.replaceAll('_',' '))}</span><span class="bar-track"><i style="width:${Math.max(2,v.mean_roc_auc*100)}%"></i></span><b>${Number(v.mean_roc_auc).toFixed(3)}</b></div>`).join('');
  const statusTotal=Math.max(1,p.booking_status.reduce((sum,x)=>sum+x.bookings,0));
  const statuses=p.booking_status.map(x=>`<div class="bar-row"><span>${esc(x.status.replaceAll('_',' '))}</span><span class="bar-track"><i style="width:${Math.max(2,x.bookings/statusTotal*100)}%"></i></span><b>${x.bookings}</b></div>`).join('');
  const monthlyMax=Math.max(1,...p.monthly_bookings.map(x=>x.bookings));
  const monthly=p.monthly_bookings.map(x=>`<div class="mini-column"><i style="height:${Math.max(4,x.bookings/monthlyMax*100)}%" title="${esc(x.month)}: ${x.bookings} bookings"></i><small>${esc(x.month.slice(5))}</small></div>`).join('');
  $('#view').innerHTML=`${head('MEASURE WHAT MATTERS','Data & model insights','Explore the allocation data, service activity and model validation.')}<div class="notice">Model metrics below describe the repository dataset and synthetic forecast. They are not evidence of live marketplace outcomes.</div>
  <div class="section-row"><h2>Worker-matching dataset</h2><span class="co-op-mark">${d.available?'20,000 ROW BASELINE':'DATA NOT FOUND'}</span></div>
  <div class="stat-grid"><div class="stat-card"><div class="stat-top">Candidate rows<span class="stat-icon">▤</span></div><div class="stat-value">${Number(d.rows||0).toLocaleString()}</div><div class="stat-note">one row per booking–worker candidate</div></div><div class="stat-card"><div class="stat-top">Booking groups<span class="stat-icon">⌑</span></div><div class="stat-value">${Number(d.bookings||0).toLocaleString()}</div><div class="stat-note">used for group-aware validation</div></div><div class="stat-card"><div class="stat-top">Workers represented<span class="stat-icon">♙</span></div><div class="stat-value">${Number(d.workers||0).toLocaleString()}</div><div class="stat-note">distinct worker identifiers</div></div><div class="stat-card"><div class="stat-top">Missing cells<span class="stat-icon">◌</span></div><div class="stat-value">${Number(d.missing_cells||0).toLocaleString()}</div><div class="stat-note">blank values across CSV fields</div></div></div>
  <div class="content-grid"><section class="panel"><div class="panel-title"><div><h2>Service category mix</h2><p>Candidate rows in the allocation dataset.</p></div></div>${services||empty('▤','No category data','Dataset profile is unavailable.')}</section><section class="panel"><div class="panel-title"><div><h2>Outcome balance</h2><p>Successful completion labels in the candidate data.</p></div></div><div class="distribution-track"><i style="width:${positivePct}%"></i></div><div class="distribution-label"><span>Completed · ${positives.toLocaleString()} (${positivePct.toFixed(1)}%)</span><span>Not completed · ${negatives.toLocaleString()}</span></div><div class="forecast-caveat">Label provenance is not documented in the repository. Confirm how these outcomes were created before describing them as observed worker performance.</div></section></div>
  <div class="section-row"><h2>Allocation model validation</h2><span class="co-op-mark">GROUPED BY BOOKING</span></div><div class="content-grid"><section class="panel"><div class="panel-title"><div><h2>Training-split model comparison</h2><p>Five-fold GroupKFold mean ROC-AUC.</p></div><span class="skill-chip">Selected · ${esc((report.selected_model||'—').replaceAll('_',' '))}</span></div>${models||empty('⌁','No model report','Run train.py to create evaluation_report.json.')}<div class="metric-pair"><span>NDCG@3 <b>${Number(report.ranking_metrics?.['ndcg@3']||0).toFixed(3)}</b></span><span>NDCG@5 <b>${Number(report.ranking_metrics?.['ndcg@5']||0).toFixed(3)}</b></span><span>Hit@1 <b>${Number(report.ranking_metrics?.hit_at_1||0).toFixed(3)}</b></span><span>ROC-AUC test <b>${Number(report.test_metrics?.roc_auc||0).toFixed(3)}</b></span></div></section><section class="panel"><div class="panel-title"><div><h2>Platform activity</h2><p>${statusTotal} booking records · ${p.reviews.count} customer reviews</p></div></div>${statuses||empty('▤','No bookings yet','Service activity will show here after the first request.')}<div class="divider"></div><div class="panel-title"><div><h2>Workload distribution</h2><p>Completed jobs among verified workers.</p></div></div><div class="forecast-big">${Number(p.completed_work_gini).toFixed(2)} <small>Gini coefficient</small></div><p class="helper-copy">0 means equal completed-job counts; higher values mean more concentration. Sample size: ${p.worker_count_for_gini} verified workers. Read with caution while the platform has few bookings.</p></section></div>
  <div class="section-row"><h2>Recent booking trend</h2><span class="co-op-mark">PLATFORM DATA</span></div><section class="panel"><div class="mini-chart">${monthly||empty('◷','No monthly data','Bookings will appear here as customers use FixMate.')}</div><div class="forecast-labels"><span>Bookings created in each month</span><span>Most recent 6 months</span></div></section>
  <div class="section-row"><h2>Demand forecasting</h2><button class="text-link" data-page="forecast">Open forecast →</button></div><div class="panel"><div class="worker-row"><span class="icon-soft">⌁</span><div><div class="worker-name">Chronological 90-day holdout · MAE ${data.forecast_model?.mae??'—'} · RMSE ${data.forecast_model?.rmse??'—'}</div><div class="worker-meta">Synthetic training panel, calendar and seasonal features. Replace with real dated bookings before operational decisions.</div></div></div></div>`;
  $$('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
}
